 if(L===1){lhs=line(a,b);constant=a*r+b;rhs=String(constant)}
 else if(L===2){lhs=`(x ${sg(b)})/${d}`;constant=(r+b)/d;rhs=frac(r+b,d)}
 else if(L===3){lhs=line(a,b);constant=(a-m)*r+b;rhs=line(m,constant)}
 else if(L===4){lhs=`${a}*(x - ${h}) ${sg(b)}`;constant=a*(r-h)+b;rhs=String(constant)}
 else{lhs=`(${a}*x ${sg(b)})/${d}`;constant=(a*r+b)/d-m*r;rhs=`${term(m,'x')} + (${frac(a*r+b-m*r*d,d)})`}
 const input=`${lhs.replaceAll('x','r')} ~ ${rhs.replaceAll('x','r')}`;
 return nq(`Use the ~ method to solve ${lhs} = ${rhs}. What is x?`,r,[r+1,r-1,-r],[input],['Rename every x to r. Delete earlier r definitions so r is an unknown parameter.','Replace = with ~. Keep the parentheses, fractions, and both sides; no rearranging is required.',`Enter the line above and read r = ${r} under Regression Parameters.`,`The original x is ${r}. Substitute it into the original equation to verify.`],'Use r instead of x and ~ instead of =.',{kind:'tilde',r,a,b,h,d,m,L,constant});
